{
  "packet_id": "H6-T02-2",
  "claim_id": "C018",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C018",
    "value": "Evidence assessments should record reliability and diagnostic value.",
    "scope": "These are attributes to assess; no particular evidence item is declared reliable or diagnostic.",
    "provenance": {
      "refs": [
        {
          "source_id": "P008",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P008 explicitly requires recording both attributes for the evidence-by-hypothesis comparison."
    }
  },
  "signal_basis": {
    "component_id": "C018_signal_basis",
    "value": "The comparison assesses each evidence item across hypotheses and checks whether removing uncertain evidence changes the ranking; weakening explanations depends on reliable, diagnostically important observations.",
    "scope": "This is a proposed assessment procedure, not a finding that any particular evidence is reliable or discriminating.",
    "provenance": {
      "refs": [
        {
          "source_id": "P008",
          "role": "SUPPORT"
        },
        {
          "source_id": "P022",
          "role": "SUPPORT"
        },
        {
          "source_id": "P023",
          "role": "SUPPORT"
        },
        {
          "source_id": "P021",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply the assessment procedure, sensitivity check, inferential criteria and proposed-observation qualifier."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C018_stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The bounded procedural claim does not require a conditional empirical warrant."
    }
  },
  "rationale": "Recording reliability and diagnostic value is warranted because the comparison uses those attributes to determine how evidence bears on competing explanations. The claim requires documenting assessments without asserting their correctness.",
  "uncertainty": "The accuracy of individual assessments remains open; this does not undermine the requirement to record them.",
  "anomalies": []
}
